"""Explicit causal reinterpretation, not automatic relabeling of manifestations."""
import json
from pathlib import Path
P=Path(__file__).resolve().parent;R=P.parent
old=json.loads((R/'relation-types-audit/pairs.json').read_text())
rows=[r for r in old if r['primary_relation'].startswith('Проявление')]
outputs={'смех','улыбка','вздох','дрожь','крик','плач','слёзы','ласка','объятие','поцелуй','вялость'}
records=[]
for r in rows:
 a,b=r['a'],r['b']
 if 'отношение' in (a,b):
  effect=b if a=='отношение' else a
  records.append(dict(a=a,b=b,status='нужно уточнить отношение',cause='отношение',effect=effect,explanation=f'Само слово «отношение» не задаёт направленность. Для «отношение → {effect}» нужно назвать отношение, например нежное; такой переход не засчитывается как общий безусловный.'));continue
 if (a,b)==('дружелюбие','симпатия'):
  records.append(dict(a=a,b=b,status='спорно',cause='симпатия',effect='дружелюбие',explanation='Симпатия может побуждать к дружелюбному поведению, но дружелюбие как установка и симпатия как расположение близки по смыслу. Для причинной пары нужно различить состояние и поведение, а не просто переименовать их.'));continue
 if (a,b)==('плач','слёзы'):cause,effect='плач','слёзы'
 else:
  assert (a in outputs)!=(b in outputs),(a,b)
  cause,effect=(b,a) if a in outputs else (a,b)
 if effect in {'ласка','объятие','поцелуй'}:
  explanation=f'{cause.capitalize()} может побудить человека к действию «{effect}». Причина здесь — мотив действия; действие не является обязательным и может иметь иные мотивы.'
 elif (cause,effect)==('плач','слёзы'):
  explanation='Плач может приводить к появлению слёз. Это причинная гипотеза для обычного словоупотребления, не утверждение об обязательном слезотечении или обо всех причинах слёз.'
 elif (cause,effect)==('усталость','вялость'):
  explanation='Усталость может приводить к вялости, то есть снижению активности. Не всякая вялость вызвана усталостью.'
 else:
  explanation=f'{cause.capitalize()} может вызвать реакцию «{effect}». Не утверждается обязательность реакции или возможность однозначно восстановить причину по ней.'
 records.append(dict(a=a,b=b,status='причинное объяснение допустимо как гипотеза',cause=cause,effect=effect,explanation=explanation))
accepted=[r for r in records if r['status']=='причинное объяснение допустимо как гипотеза']
assert len(records)==35 and len(accepted)==31
assert len({tuple(sorted((r['a'],r['b']))) for r in records})==35
for r in records:assert {r['a'],r['b']}=={r['cause'],r['effect']}
report=dict(scope='Повторно рассмотрены именно 35 пар, ранее отнесённых к проявлению. Не полный причинный аудит 1596 возможных внутренних пар.',counts={'reviewed':35,'plausible_causal':31,'requires_specific_attitude':3,'ambiguous':1},criterion='A может вызвать B в понятном контексте или мотивировать действие B. Нужен причинный рассказ без подмены значений; обязательность, единственность причины и обратный вывод не требуются.',status='Авторские гипотезы. Типы игры и принятый граф не изменены.',pairs=records)
(P/'review.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
lines=['# Повторная проверка причины','', 'Пользователь указал на естественную связь «радость — причина улыбки». Прежний ноль у причинности отражал выбранный способ классификации аннотаций, а не отсутствие причинных объяснений. Вывод о необходимости отдельного проявления был преждевременным.','', '## Критерий','', '**Первое понятие может вызвать второе либо побудить к нему. Игрок объясняет, как.** Причина не обязана всегда приводить к следствию и не обязана быть единственной. Обратный вывод недопустим: улыбка сама по себе не доказывает радость. Простого совместного появления двух явлений недостаточно.','', '## Результат','', 'Из 35 ранее выделенных пар проявления для 31 записано самостоятельное причинное объяснение, три требуют конкретизации отношения, одна остаётся спорной. Это оценка правдоподобия для игры, а не 31 научно установленная причинная зависимость. Проверены 35 известных пар, не все возможные пары колоды и не все возможные причинные ходы.','', 'Примеры: Радость → Улыбка; Страх → Дрожь; Горе → Плач; Облегчение → Вздох; Усталость → Вялость; Любовь → Объятие (мотив действия). Направление совпадает с классической причиной: причина → следствие. Прежнее предложение направления проявление → чувство здесь не применяется.','', 'Старые пять типов предварительно покрывали 67 из 106 пар. Вместе с 31 причинным объяснением получается 98 из 106, но это арифметическое покрытие по гипотезам, не подтверждение правильности всех пар: старые оговорки к виду, свойству и составляющим сохраняются. Количество внутренних пар не увеличивается; меняется возможное обоснование уже существующих пар.','', '## Альтернативы названию','', '- **Выражение** — наиболее понятная замена для улыбки, смеха, ласки; менее естественна для вялости от усталости.','- **Признак** — обозначает, по чему можно предположить состояние; не равно причине и не означает однозначную диагностику.','- **Отражение** — допускает больше толкований и хуже задаёт проверяемое правило.','', 'Рекомендация: пока не вводить отдельный шестой тип. Сохранить причинность; для интерфейса можно предложить название «Вызывает», но это ещё не принятое изменение. Уточнение «может вызвать» соответствует пользовательскому примеру. Если после испытания останутся выражения без убедительного причинного объяснения, рассмотреть для них отдельное «Выражение».','', '## Разбор каждой пары','', '| Причина → следствие | Решение | Объяснение |','|---|---|---|']
for r in records:lines.append(f"| {r['cause']} → {r['effect']} | {r['status']} | {r['explanation']} |")
lines+=['', 'Результат не отменяет проверку контекста голосованием и не меняет бонусы или направления старых типов. Следующий шаг при утверждении набора — проверить оставшиеся восемь не покрытых пар и спорные старые классификации, затем пересчитать степени карт.','', 'Воспроизведение: `python docs/deck-research/emotions-ru/causal-review/build.py`. Источник: ../relation-types-audit/pairs.json. Сохранены направления и объяснения всех 35 решений; пары и числа сверены скриптом.']
(P/'README.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(report['counts']))
